#!/usr/bin/env python3
"""R532-9 adaptation of R533-8's binding_probe.py (sha256 3047858d...bf72):
the direct-delivery workaround (the direct port call and its positive control)
is removed, and the required composed-delivery assertion must now PASS.
usage: binding_probe_nodirect.py REPO LWSRP WORK

Probe the required ACMP-to-SRP delivery through the composed application.

Only the test translation unit is copied/extended. Production sources are
compiled from the exact checkout. Existing fake environment callbacks observe
the ACMP handoff; direct adapter delivery is a separate positive control.
Exit 0 means the missing-delivery failure was reproduced at both interfaces.
"""
from pathlib import Path
import sys

root = Path(sys.argv[1]).resolve()
lwsrp = Path(sys.argv[2]).resolve()
work = Path(sys.argv[3]).resolve()
sys.path.insert(0, str(root / "sw/firmware/ctrl/test"))
import srp_arms
import fw_gtest
from ctrl_build import CTRL, Tree

probe = work
probe.mkdir(parents=True, exist_ok=True)
extra = r'''
namespace {
TEST_F(AcmpMailbox, R533ComposedAcmpDeliveryReachesSrp) {
    mbx_model_reset(&model);
    for (unsigned i = 0; i < MBX_N_IF; ++i) {
        mbx_model_set_gm(&model, i, kGm0, 0);
        mbx_model_set_link(&model, i, true);
    }
    const ctrl_app_config cfg = three_way();
    ASSERT_TRUE(ctrl_app_start(&app, &cfg));
    attach_srp();
    settle();
    for (unsigned i = 0; i < MBX_N_IF; ++i) {
        fk.clear();
        bind(i);
        ASSERT_TRUE(offer(answer(i), spec::MULTICAST_MAC, i));
        settle();
        bool requested = false;
        for (const auto& call : fk.calls) {
            requested = requested || (call.kind == Call::SRP && call.index == i &&
                         call.flag && call.stream.stream_id == kSid);
        }
        ASSERT_TRUE(requested) << "ACMP accepted the response and requested this stream";
        for (unsigned pass_number = 0; pass_number < 32u; ++pass_number) {
            mbx_model_advance_ms(&model, 10u);
            settle();
        }
        std::printf("R533 interface=%u ACMP_requested=%u SRP_bound=%u\n", i,
                    static_cast<unsigned>(requested),
                    static_cast<unsigned>(srp_adapter.ifs[i].sinks[i].bound));
        EXPECT_TRUE(srp_adapter.ifs[i].sinks[i].bound)
            << "R533 required composed delivery is absent";
    }
    srp_mbx_destroy(&srp_adapter);
}
}
'''
original = root / "sw/firmware/ctrl/test/test_acmp_mbx.cpp"
(probe / original.name).write_text(original.read_text() + extra)
srp_arms.HERE = probe
selected = "AcmpMailbox.R533ComposedAcmpDeliveryReachesSrp"
for count in (1, 2):
    out = probe / f"if{count}"
    result = srp_arms.arm_srp(Tree(CTRL, out, out / "reuse", fw_gtest.Build(jobs=2)),
                              lwsrp, count,
                              test=(original.name, selected))
    print(result.log, flush=True)
    assert result.rc == 0, "required composed delivery must pass without direct delivery"
    assert "R533 required composed delivery is absent" not in result.log
    assert result.log.count("SRP_bound=1") == count, "every tested interface reports SRP_bound=1"
print("PASS: accepted ACMP requests reach the attached SRP adapter through the composition, no direct delivery")

// Reviewer probe (R532-9): appended to srp_binding.hpp in a disposable copy.
// One PROBE_TX_RESPONSE whose stream_vlan_id is 0 (outside 1..4094): count how
// long the composed loop refuses to sleep with no further input, and what
// ACMP and SRP each report meanwhile.
namespace {
class SrpBindingVidProbe : public SrpBinding {};
TEST_F(SrpBindingVidProbe, InvalidVidKeepsTheLoopAwakeWithoutInput) {
    bind(0);
    auto invalid=answer(0); invalid.vlan=0;
    ASSERT_TRUE(offer(invalid,spec::MULTICAST_MAC,acfg.sink_interface[0]));
    settle();
    unsigned awake=0, first_sleep=0;
    for (unsigned ms=0; ms<12000u; ++ms) {
        mbx_model_advance_ms(&model,1u);
        for (unsigned n=0;n<4u;++n) {
            if (ctrl_loop_service(&app.loop)!=0u) { ++awake; } else { if (!first_sleep) first_sleep=ms+1u; break; }
        }
        if (ms==5000u) {
            std::printf("  probe: t=5 s acmp state %d (6=SETTLED_NO_RSV) srp bound %d request pending %d\n",
                        static_cast<int>(core()->sinks[0].state),sink(0).bound,app.srp_requests[0].pending);
        }
    }
    std::printf("  probe: 12 s without input: %u non-idle passes, first idle pass at %u ms, owed passes %u\n",
                awake,first_sleep,static_cast<unsigned>(app.loop.stats.owed_passes));
    EXPECT_LT(first_sleep,100u) << "PROBE-VID the loop sleeps soon after a permanently refused binding";
}
} // namespace

// Reviewer probe (R532-9): appended to srp_binding.hpp in a disposable copy.
// After a real bind and PROBE_TX_RESPONSE, a matching MSRP Talker Advertise is
// received on the sink's interface and refreshed every second. Milan v1.2
// 5.5.3.5.42 moves the sink to SETTLED_RSV_OK once the Talker attribute is
// registered; 5.5.3.5.36 withdraws SRP only when TMR_NO_TK (10 s) expires
// without one.
namespace {
class SrpBindingProbe : public SrpBinding {};
std::vector<uint8_t> probe_talker_frame(unsigned event) {
    std::vector<uint8_t> v(25);
    wire_put_be(v.data(),kSid,8); wire_put_be(v.data()+8,kDa,6); wire_put_be(v.data()+14,2,2);
    wire_put_be(v.data()+16,224,2); wire_put_be(v.data()+18,1,2); v[20]=0x60;
    const unsigned list=2+v.size()+1+2;
    std::vector<uint8_t> f(14+1+4+list+2);
    wire_put_be(f.data(),0x0180c200000eull,6);
    wire_put_be(f.data()+6,0x020304010203ull,6);
    wire_put_be(f.data()+12,0x22ea,2);
    auto *p=f.data()+14; p[1]=1; p[2]=v.size();
    wire_put_be(p+3,list,2); wire_put_be(p+5,1,2);
    std::memcpy(p+7,v.data(),v.size()); p[7+v.size()]=event*36;
    return f;
}
TEST_F(SrpBindingProbe, RegisteredTalkerReachesAcmpAndBindingSurvivesNoTk) {
    for (unsigned k=0;k<2u;++k) {
        bind(k); response(k); expect_stream(k);
        ASSERT_EQ(core()->sinks[k].state,ACMP_SETTLED_NO_RSV);
    }
    bool withdrawn[2]{};
    for (unsigned second=0; second<12u; ++second) {
        for (unsigned k=0;k<2u;++k) {
            const auto f=probe_talker_frame(second==0 ? 0u : 1u);
            ASSERT_TRUE(mbx_model_rx(&model,f.data(),f.size(),acfg.sink_interface[k]));
        }
        settle();
        if (second==0) {
            for (unsigned k=0;k<2u;++k) {
                EXPECT_NE(sink(k).desired,0u) << "PROBE-TK0 SRP registered the matching Talker, sink " << k;
                EXPECT_EQ(core()->sinks[k].state,ACMP_SETTLED_RSV_OK)
                    << "PROBE-TK1 ACMP learns the registered Talker (Milan 5.5.3.5.42), sink " << k;
            }
        }
        for (unsigned ms=0; ms<1000u; ms+=10u) {
            mbx_model_advance_ms(&model,10u); settle();
            for (unsigned k=0;k<2u;++k) {
                if (!sink(k).bound && !withdrawn[k]) {
                    withdrawn[k]=true;
                    std::printf("  probe: sink %u SRP binding withdrawn at t=%u ms after the first Talker Advertise (acmp state %d, probes sent so far)\n",
                                k,second*1000u+ms+10u,static_cast<int>(core()->sinks[k].state));
                }
            }
        }
    }
    for (unsigned k=0;k<2u;++k) {
        EXPECT_NE(sink(k).desired,0u) << "PROBE-TK0 Talker still registered after 12 s, sink " << k;
        EXPECT_TRUE(sink(k).bound) << "PROBE-TK2 a healthy registered binding survives TMR_NO_TK, sink " << k;
        EXPECT_NE(core()->sinks[k].state,ACMP_PRB_W_RESP) << "PROBE-TK3 no reprobe of a registered binding, sink " << k;
        std::printf("  probe: sink %u acmp state %d srp bound %d desired %u\n",k,
                    static_cast<int>(core()->sinks[k].state),sink(k).bound,sink(k).desired);
    }
}
} // namespace
